/* Self-check practice questions. Runs entirely in the student's browser. */
(function(){
 'use strict';
 const banks={
 unit10:[["Which web technology primarily defines the content and structure of a webpage?",["JavaScript","HTML","CSS","Web hosting"],1,"HTML provides headings, paragraphs, buttons and other structural elements."],["Which web technology primarily controls colours, fonts and spacing?",["HTML","JavaScript","CSS","DNS"],2,"CSS is responsible for most visual styling."],["Which technology often makes a webpage respond to a button click?",["JavaScript","JPEG","CSS alone","A domain name"],0,"JavaScript can listen for events and update webpage content."],["Which task is a suitable beginner use of JavaScript on a library site?",["Unlock restricted borrower files","Display public opening hours when a button is clicked","Replace all server security","Change a database password"],1,"Showing general public information is appropriate for simple client-side interaction."],["What does client-side JavaScript usually mean?",["Code running in the visitor’s browser","A script stored only on paper","Code that runs only in printers","A new type of CSS"],0,"Client-side code executes in the browser on the visitor’s device."],["What is a JavaScript statement?",["A folder name","An instruction to be executed","A web address extension","A heading style"],1,"Statements express actions or declarations in a script."],["Which of these is a JavaScript string?",["17","true","\"Library\"","false"],2,"A quoted text value is a string."],["Which of these is a JavaScript number?",["\"20\"","20","\"twenty\"","true"],1,"20 without quotes is a numeric value."],["Which value is a Boolean?",["\"Yes\"","23","false","\"false\""],2,"Booleans are true or false without quotation marks."],["What does the line const service = \"Library\"; do?",["Creates an HTML link","Declares a variable and gives it text","Styles the webpage","Submits a request"],1,"const declares a variable binding with the string value Library."],["When is let useful?",["When a value may be reassigned","Only for HTML headings","To make text bold","To create an image file"],0,"A let variable can be reassigned later, such as a growing counter."],["Which line is a JavaScript comment?",["<p>Text</p>","// Explain the next line","body { color: red; }","const x = 4;"],1,"Two forward slashes begin a single-line comment."],["Is JavaScript case-sensitive?",["No, capitals never matter","Only for file names","Yes, names with different capitalisation may be different","Only for CSS properties"],2,"Code such as openPage and openpage refers to different names."],["What is a function?",["An image format","A reusable block of instructions","A website domain","An HTML table row"],1,"Functions group instructions so they can be called as needed."],["What does an if statement allow?",["Making a decision based on a condition","Changing the computer monitor","Creating a domain name","Automatically encrypting records"],0,"if runs code only when its condition is truthy."],["What is the DOM?",["A model of the webpage document and its elements","A type of computer cable","A library classification scheme","A server password manager"],0,"The Document Object Model represents webpage elements for scripts to access."],["What does document.getElementById(\"notice\") do?",["Deletes the entire website","Locates an element with id=\"notice\"","Changes every font automatically","Downloads an image"],1,"getElementById retrieves the element whose ID matches the supplied string."],["Which property safely changes the text inside an element?",["textContent","domainName","tableHeader","fontSizeOnly"],0,"textContent sets text rather than interpreting it as HTML markup."],["What is an event?",["An action such as a button click","Only a classroom timetable entry","A file extension","A fixed CSS colour"],0,"Browsers can detect clicks, changes, keyboard input and other events."],["What does addEventListener(\"click\", ...) do?",["Adds a web address","Connects code to a click event","Creates a new HTML page","Prevents the computer from sleeping"],1,"The listener runs its callback when a click occurs."],["Which HTML element is usually best for an action that JavaScript performs?",["<button>","<meta>","<title>","<table>"],0,"A button has built-in keyboard and accessibility behaviour."],["What happens when a script updates a paragraph using textContent?",["The paragraph’s displayed text changes","The web server is always restarted","The database is automatically saved","All CSS is removed"],0,"textContent replaces the chosen element’s text."],["What does console.log(\"Ready\") do?",["Displays text in the webpage body","Sends text to the browser’s developer console","Creates a user account","Submits a form"],1,"console.log is for console output, not a visible webpage message."],["What does the defer attribute do for a traditional external script?",["Encrypts the script","Defers execution until the HTML has been parsed","Makes CSS load first in every case","Deletes unused HTML"],1,"defer lets the browser parse HTML before executing the external script."],["Why might an external script.js file be useful?",["It separates reusable behaviour from HTML","It guarantees all forms are secure","It removes the need for HTML","It hides the source from every visitor"],0,"External scripts can be reused and maintained separately."],["Which line correctly loads an external JavaScript file?",["<script src=\"script.js\" defer></script>","<css href=\"script.js\">","<img src=\"script.js\">","<link rel=\"button\" href=\"script.js\">"],0,"Use a script element with the src attribute."],["What is a common reason getElementById() returns null?",["The id is misspelled or the element does not yet exist","The text is too colourful","The image is too small","The paragraph has too many words"],0,"The ID must match and the element must be present when the script executes."],["What is a useful response after a visitor submits a practice enquiry?",["A visible message explaining what happened","Silence and no feedback","A random animation","Automatic access to confidential files"],0,"Clear feedback helps visitors understand the outcome."],["What does event.preventDefault() do in a submit handler?",["Stops the event’s normal default action","Automatically stores a record","Authenticates a visitor","Starts a payment"],0,"It can prevent a form’s default submission while a demonstration runs."],["Does JavaScript form validation replace secure server-side validation?",["Yes, always","Only if the page is colourful","No, server-side checks are still necessary","Only on mobile phones"],2,"Browser-side checks can be bypassed and cannot enforce back-end security."],["Can a static practice form securely store real personal records just by adding JavaScript?",["Yes, with one alert()","No, secure storage and processing require a suitable backend","Only if the button is red","Yes, if the page has a footer"],1,"JavaScript alone does not provide the required trusted storage and access controls."],["Which is suitable information for a public records-centre demo?",["A restricted staff personnel file","Secret login credentials","General public request procedures","Unredacted private medical information"],2,"Public procedures can be shown without disclosing confidential records."],["Why use an aria-live region for a status message?",["To help assistive technologies announce updates","To create a new database","To change the URL","To hide information from visitors"],0,"An aria-live region can inform screen-reader users when content changes."],["Which is a good accessibility practice for interactive controls?",["Use keyboard-operable buttons with clear labels","Use only clickable images without labels","Hide focus indicators","Communicate errors using colour alone"],0,"Native buttons and descriptive labels help a wider range of users."],["What happens if JavaScript fails to load on a well-designed information page?",["Important public content should ideally remain accessible","All text must disappear","All users should receive restricted access","The site must delete its pages"],0,"Progressive enhancement keeps essential information usable without scripts."],["What is a useful role for JavaScript on a records-centre practice page?",["Reveal public enquiry instructions based on a selected topic","Grant access to protected records by hiding a button","Publish real passwords","Override server permissions"],0,"JavaScript can improve the interface but must not control sensitive access."],["What does let clicks = 0; clicks = clicks + 1; produce?",["An image named clicks","The new clicks value is 1","A webpage link","A new JavaScript file"],1,"The variable increases from zero to one."],["Which pair of IDs must match in a DOM example?",["HTML id=\"message\" and getElementById(\"message\")","HTML id=\"message\" and getElementById(\"notice\")","HTML id=\"message\" and getElementById(\"other\")","A CSS colour and a filename"],0,"The string used in getElementById must match the target ID."],["Which choice best explains the difference between HTML and JavaScript?",["HTML provides content; JavaScript can change or respond to that content","HTML encrypts records; JavaScript prints paper","HTML is only for images; JavaScript is only for colours","They are identical"],0,"HTML structures information; JavaScript enables dynamic behaviour."],["A student changes the button label but not the JavaScript ID. What should they check?",["Whether the element ID and script selector still match","Whether the colour is green","Whether their name appears in the title","Whether they have 50 paragraphs"],0,"The script identifies elements by the ID, not by the visible label."]],
 unit9:[["Which question best measures usability?",["Can a visitor complete an important task?","Is the homepage very long?","Does the designer like the colours?","How many animations are present?"],0,"Usability is about whether people can achieve their goals."],["What is the user interface (UI)?",["Only the web server hardware","The controls and visible elements people interact with","An organisation’s filing system","The entire Internet"],1,"Menus, fields and buttons are common interface elements."],["What does UX stand for?",["Universal extraction","User experience","Unique extension","User execution"],1,"UX describes the broader experience of using the service."],["What is a key difference between UX and UI?",["UX considers the overall experience; UI refers to interaction elements","UI only refers to printed documents","UX means colour and UI means database","They always have identical meanings"],0,"The interface is one important part of a wider user experience."],["What should guide decisions about homepage content?",["An unrelated website’s menu","Common tasks of intended visitors","The designer’s favourite font alone","The number of pictures available"],1,"A user-centred homepage prioritises real visitor needs."],["Which library task is most appropriate to test?",["View restricted borrower passwords","Find opening hours","Change a lecturer’s grades","Install server drivers"],1,"Opening hours are a common, public information task."],["Which records-centre task is suitable for a public site?",["Download confidential personnel files","Access staff login credentials","Edit an official retention schedule without authorisation","Find public request procedures"],3,"Public procedures may be explained without disclosing restricted records."],["What is a realistic user scenario?",["A CSS property name","A student using a phone to find library hours","A server model number","A random colour choice"],1,"Scenarios combine a user, task and context."],["Why should navigation labels use familiar words?",["It makes all pages shorter automatically","Visitors can predict where links lead","It guarantees the website never changes","It eliminates the need for testing"],1,"Familiar labels support findability and reduce confusion."],["Which link label is clearest?",["Search the Catalogue","LISOPAC 4B","Click here","More info"],0,"Descriptive labels state an action or destination."],["What does information architecture concern?",["Only a website’s colours","The cable type in the building","Organisation and labelling of website content","Only image compression"],2,"Clear content organisation makes information easier to find."],["What is a sensible homepage menu for a small service?",["Only unlabeled icons","List A, List B, List C, List D","Main, Other, Extra, Miscellaneous","Home, Services, Catalogue, Contact"],3,"Specific, expected labels help visitors orient themselves."],["What is visual hierarchy?",["Making all text equally large","Removing all headings","Adding flashing animation to every card","Presenting important information so it stands out appropriately"],3,"Hierarchy helps visitors scan and prioritise information."],["Why is whitespace useful?",["It automatically secures forms","It separates groups of related content","It always wastes screen space","It turns HTML into JavaScript"],1,"Spacing makes the relationship between elements clearer."],["Which typography choice supports readability?",["Entire pages in all capitals","Tiny low-contrast body text","Legible text size and adequate spacing","Many unrelated decorative fonts"],2,"Readable text reduces effort for visitors."],["Why should important links not be labelled only “click here”?",["The destination is unclear out of context","Browsers reject those words","Links need exactly two words","It prevents CSS from loading"],0,"Descriptive link text helps scanning and assistive-technology navigation."],["What is a common sign of inconsistent navigation?",["The main content uses headings","All links have clear labels","A shared menu remains at the top","The same service appears under different labels on each page"],3,"Consistency reduces relearning as visitors change pages."],["Which is an example of feedback?",["A confirmation that an enquiry was received","An unrelated background picture","An image without text","A decorative border"],0,"Feedback explains what happened after a visitor acts."],["Which form error message is most useful?",["Something happened","Enter a valid email address, such as name@example.com","Error!","E430"],1,"Helpful errors identify what went wrong and how to correct it."],["Why should a form label remain visible?",["Visitors can identify its purpose during entry","All placeholders are always read by assistive tools","A visible label automatically validates identity","Labels make a database unnecessary"],0,"Labels provide context and support accessible interaction."],["What is an accessibility benefit of keyboard navigation?",["It prevents every security vulnerability","People can use controls without a mouse","It reduces the number of paragraphs","The website becomes automatically private"],1,"Keyboard access supports different input needs."],["Which test checks keyboard accessibility?",["Count the photographs","Make the page background darker","Use Tab and Enter to navigate and activate controls","Inspect the hosting bill"],2,"Keyboard testing can reveal unreachable controls or missing focus."],["What is visible keyboard focus?",["An indicator showing which control receives keyboard input","A file download progress bar","A hidden browser cookie","The site logo"],0,"Focus visibility helps keyboard users know their current position."],["What is the main purpose of informative image alt text?",["Increase the screen resolution","Prevent printing","Encrypt the image","Convey the image’s meaning when it is not seen"],3,"Text alternatives communicate useful visual information."],["Which of the following is one WCAG guiding principle?",["Decorative","Operable","Expensive","Animated"],1,"WCAG uses Perceivable, Operable, Understandable and Robust."],["What does WCAG “Perceivable” broadly mean?",["Information can be perceived through users’ available senses and tools","Every page must contain video","Only sighted visitors matter","All text must be italic"],0,"Perceivable content includes text alternatives and adaptable presentation."],["Why should errors not be indicated by colour alone?",["HTML does not support colours","Browsers automatically remove red text","It is illegal to use backgrounds","Some people may not distinguish colours; include text cues"],3,"Use messages, labels or other indicators as well as colour."],["What is a key limitation of a quick accessibility checklist?",["It proves a page meets all standards","It replaces all user testing","It does not establish full WCAG conformance","It measures network speed precisely"],2,"A preliminary review only covers some issues."],["What is a mobile usability issue?",["A page requires sideways scrolling to read ordinary text","Cards stack into one column","Images fit their containers","Readable labels remain visible"],0,"Page-wide overflow makes narrow-screen reading difficult."],["Why test a page at more than one screen width?",["It automatically verifies security","Layout and controls may behave differently","It removes the need to check navigation","Websites display the same arrangement everywhere"],1,"Responsive design needs practical checks across sizes."],["What should be the first step in a basic usability evaluation?",["Choose a page, intended visitor and task","Change all colours","Write the final recommendation","Add random animations"],0,"Task selection gives evaluation a concrete purpose."],["What does a success criterion do?",["Replaces all content","Defines an image format","Chooses a website domain","States what successful task completion looks like"],3,"It makes outcomes observable rather than purely subjective."],["Which observation is evidence rather than an unsupported opinion?",["Opening hours were found under About → Administration","The website is bad","I dislike the designer","The website feels old-fashioned"],0,"Evidence identifies what happened and where."],["Which recommendation is most actionable?",["Rename “RMD Form 17B” to “Request a Public Record”","Improve the website","Use more colours","Make everything better"],0,"Specific changes with user benefits are easier to implement."],["What should a good finding include?",["Only a personal rating","Only the evaluator’s name","Only the homepage colour","Location, issue, impact and recommendation"],3,"Findings should link observed problems to user needs and solutions."],["Which issue should usually be prioritised highest?",["A low-priority paragraph is one line longer","A minor margin inconsistency","A decorative icon is slightly different","A main request button cannot be activated by keyboard"],3,"Problems blocking essential tasks require urgent attention."],["Why should a real records site protect restricted content?",["Colour contrast replaces access checks","Usability does not override confidentiality and access controls","A pretty homepage ensures all data is public","All archive materials are unrestricted"],1,"Access policies and security remain essential."],["How should practice evaluation data be chosen?",["Use real staff passwords","Publish named borrowers","Use fictional records and sample visitors","Copy confidential files"],2,"Fictional data avoids exposing real personal and restricted information."],["What is the purpose of user testing?",["Only confirm that the HTML file is valid","Guarantee everyone likes the site","Observe whether intended users can complete realistic tasks","Replace all accessibility checks"],2,"User testing reveals barriers that designers may overlook."],["Which statement about form previews is correct?",["A styled form enforces access rights","All fields are encrypted by CSS","Every HTML button automatically saves to a database","A visual confirmation does not prove a server saved a request"],3,"Back-end processing and security are separate from visual form design."],["Why is an eight-point score not a complete usability measure?",["It describes the server response time","It can never be calculated","It proves all visitors will succeed","It checks limited criteria and may omit user tasks and barriers"],3,"A short checklist is only one source of evaluation evidence."]],
 unit8:[["What is the main purpose of responsive web design?",["Make a website adapt to different available screen widths","Always use the same fixed width","Make all text smaller on phones","Remove content on small screens"],0,"Responsive layouts preserve access and readability across device sizes."],["What is a viewport in web design?",["The area available for a webpage in the browser","A database containing website data","A type of HTML list","A file that stores CSS"],0,"The viewport is the browser area used to display the page."],["Which meta tag commonly helps mobile browsers render device-width layouts?",["<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">","<meta name=\"charset\" content=\"wide\">","<meta name=\"mobile\" content=\"small\">","<link rel=\"viewport\" href=\"css\">"],0,"The viewport meta tag tells mobile browsers to use the intended device-width layout."],["What does mobile-first design mean?",["Start with a usable narrow-screen layout, then enhance at wider widths","Design only for phones","Create desktop pages first and shrink all text","Use JavaScript for every style"],0,"Mobile-first CSS usually starts with a compact base layout and adds wider-screen rules."],["Which layer lies directly around the content in the CSS box model?",["Padding","Margin","Viewport","Media query"],0,"Padding sits between content and border."],["Which layer creates space outside an element’s border?",["Margin","Padding","Content","Font size"],0,"Margin separates the outside of an element from neighbouring elements."],["What is the normal order of CSS box-model layers from inside to outside?",["Content, padding, border, margin","Margin, border, padding, content","Content, margin, padding, border","Padding, content, margin, border"],0,"The four box-model layers extend from the content outward."],["What does box-sizing: border-box do?",["Includes padding and border within the declared width","Adds margin inside the content","Makes the page full screen","Removes every border"],0,"With border-box, width includes content, padding and border."],["With default content-box, a box has width 200px, left/right padding 10px and borders 2px each. What is its outer width before margins?",["224px","200px","212px","240px"],0,"200 + 10 + 10 + 2 + 2 = 224 pixels."],["With border-box and width: 300px, which statement is true?",["The declared width includes padding and border","The content must be 300px plus padding","Margins become part of the declared width","The box cannot have a border"],0,"box-sizing: border-box includes content, padding and border in width, not margin."],["Which width rule generally helps a large page container shrink on a phone?",["width: 100%; max-width: 1000px;","width: 1400px;","min-width: 1400px;","font-size: 6px;"],0,"A percentage width with max-width fits narrow containers without growing indefinitely."],["What is the role of max-width: 900px?",["Prevent an element from growing beyond 900px","Force it to be at least 900px","Make all children 900px","Set the font to 900px"],0,"max-width puts an upper limit on element width."],["What does margin-inline: auto often do to a narrower block?",["Centre it horizontally when spare space exists","Remove its content","Make the text bold","Create a new HTML element"],0,"Auto inline margins can share leftover horizontal space and centre a block."],["Which CSS property adds space inside a service card?",["padding","margin","display","z-index"],0,"Padding creates space between content and the border."],["Which property separates flex items without adding margins to each one?",["gap","color","font-weight","text-decoration"],0,"gap controls spacing between items in flex and grid containers."],["Which property activates Flexbox on a container?",["display: flex;","position: table;","font-style: flex;","border: flex;"],0,"display: flex establishes a flex formatting context for direct children."],["What happens to the direct children of a display:flex container?",["They become flex items","They become HTML tables","They are automatically hidden","They must become images"],0,"Flexbox controls the layout of the container’s direct child elements."],["What does flex-direction: column mean?",["Arrange flex items along a vertical main axis","Always put items in three columns","Add a column to a database","Make every item full screen"],0,"Column places flex items along the vertical main axis."],["Which property allows Flexbox items to move onto another line?",["flex-wrap: wrap;","flex-wrap: never;","text-align: wrap;","height: auto;"],0,"With flex-wrap: wrap, items can form additional lines when space is insufficient."],["What does flex: 1 1 240px broadly express?",["An item may grow or shrink around a preferred size of 240px","An item must always be exactly 240px","The item has 1px padding and 1px margin","The item can never wrap"],0,"The flex shorthand includes grow, shrink and basis values."],["What is the purpose of justify-content in Flexbox?",["Distribute items along the main axis","Set a page title","Choose a database","Control image file size"],0,"justify-content aligns or distributes available space along the main axis."],["What is the purpose of align-items in Flexbox?",["Align items along the cross axis","Make all links underlined","Set only background images","Turn Flexbox into a table"],0,"align-items aligns flex items along the cross axis."],["What does @media (min-width: 720px) mean?",["Apply enclosed rules when the viewport is at least 720px wide","Apply rules only at exactly 720px","Make every element 720px tall","Require JavaScript to run"],0,"min-width media queries apply when the tested viewport width meets or exceeds that value."],["Do CSS media queries need JavaScript to work?",["No, the browser evaluates CSS media conditions","Yes, always","Only if there are links","Only when the page contains tables"],0,"The browser applies media query rules automatically."],["How should a breakpoint usually be chosen?",["Where the actual content needs a layout adjustment","At a fixed width for every site regardless of content","Only from the brand colour","According to the student’s name"],0,"Breakpoints should respond to content and available space, not arbitrary device labels."],["Which rule helps images scale down inside a narrow container?",["max-width: 100%; height: auto;","width: 1800px;","margin-left: 900px;","white-space: nowrap;"],0,"max-width prevents oversizing and height:auto preserves the intrinsic proportions."],["What is a useful way to handle a genuinely wide HTML table on a phone?",["Place the table inside a container with overflow-x: auto","Turn every cell into an image","Shrink all text to unreadable size","Delete the column headers"],0,"A scrollable wrapper allows the table to remain structured while limiting side scrolling to the table area."],["Which issue is a warning sign of poor responsive layout?",["The whole page requires horizontal scrolling on a phone","A service card wraps onto the next row","A heading uses two lines","An image scales down proportionally"],0,"Page-wide horizontal overflow often indicates oversized or inflexible content."],["Which approach keeps links usable on small screens?",["Allow the navigation to wrap or stack with sufficient spacing","Place all links in a single unbreakable 1800px row","Make the links invisible","Remove keyboard access"],0,"Visible, readable navigation should adapt to narrow space."],["Why should a page be tested with long headings and actual-length descriptions?",["Long content can wrap or overflow where short examples fit","Long headings automatically encrypt information","Text length never affects layout","All browsers shorten long content automatically"],0,"Realistic content reveals layout problems that placeholders can conceal."],["What should a tester inspect at phone width?",["Readability, link access, card wrapping and horizontal overflow","Only the logo colour","Only the number of HTML files","Only server storage"],0,"Responsive evaluation includes both visual and interaction checks."],["What is a sensible way to test responsive behaviour?",["Resize the browser or use responsive device mode","Print the source code only","Check only a desktop screenshot","Remove all CSS"],0,"Resizing or device emulation makes layout changes visible."],["Which CSS rule is most likely to cause overflow on a narrow phone?",["width: 1100px;","max-width: 100%;","flex-wrap: wrap;","box-sizing: border-box;"],0,"A large fixed width may exceed the viewport."],["Which CSS feature is well suited to a row of library service cards?",["Flexbox","HTML comments","A favicon","A metadata description"],0,"Flexbox helps align and wrap a set of related cards."],["On a records-centre website, why might service cards stack on phones?",["To keep each service description easy to read and select","To hide public information","To eliminate all links","To avoid using semantic HTML"],0,"Stacking prevents narrow cards from crowding or overflowing."],["What does flex-direction: row usually do?",["Arrange items along a horizontal main axis","Place items in a single vertical column","Set letter spacing","Start a new HTML document"],0,"Row is a common horizontal Flexbox direction."],["What is the best use of a media query in a small service page?",["Change its layout when more horizontal space becomes available","Insert actual confidential records","Change a user password","Send form submissions to a server"],0,"Media queries adjust styling based on conditions such as viewport width."],["Which statement about responsive design is accurate?",["Responsive design still needs meaningful HTML and accessible controls","Responsive CSS guarantees secure records access","Responsive design replaces all navigation","Only desktop computers need responsive layouts"],0,"Responsiveness improves presentation, not security or document semantics."],["Which CSS value allows a service-card container to wrap items?",["flex-wrap: wrap;","flex-shrink: hidden;","font-weight: responsive;","text-align: inline;"],0,"Flex wrapping allows items to take new lines."],["If changing the media query breakpoint alters the tablet layout, what does that demonstrate?",["The breakpoint controls when the alternative rules apply","The HTML files were deleted","The browser stopped reading CSS","The stylesheet becomes a database"],0,"The media condition determines when the rules inside it become active."]],
 unit7:[["What does CSS stand for?",["Cascading Style Sheets","Computer Style Syntax","Creative Software System","Content Structure Sheet"],0,"CSS stands for Cascading Style Sheets."],["Which technology primarily defines webpage structure?",["HTML","CSS","A spreadsheet","An image editor"],0,"HTML defines the structure and meaning of a webpage."],["What is CSS mainly used for?",["Presentation and styling","Storing database records","Encrypting passwords","Creating internet connections"],0,"CSS controls the visual presentation of HTML content."],["In h1 { color: teal; }, which part is the selector?",["h1","color","teal",";"],0,"h1 selects level-one headings."],["What is the property in p { font-size: 18px; }?",["font-size","18px","p","{ }"],0,"font-size is the CSS property being changed."],["What is the value in body { background-color: #ffffff; }?",["#ffffff","body","background-color","background"],0,"#ffffff is the value assigned to background-color."],["Which punctuation separates a property from a value?",["A colon (:)","A comma (,)","A full stop (.)","A slash (/)"],0,"A declaration normally uses property: value;."],["Which punctuation commonly ends a CSS declaration?",["A semicolon (;)","A question mark (?)","A quotation mark (\")","A hash (#)"],0,"Semicolons separate CSS declarations."],["How does a CSS comment begin?",["/*","//","<!--","**"],0,"CSS comments begin with /* and end with */."],["Which element is used to link an external stylesheet in HTML?",["<link>","<script>","<table>","<title>"],0,"The link element with rel=\"stylesheet\" points to CSS."],["Where is an internal <style> element normally placed?",["Inside the HTML head","Inside the browser address bar","Inside a CSS file as HTML","Only inside a table"],0,"Internal styles normally appear in a style element in the document head."],["Which filename most clearly represents a stylesheet?",["styles.css","styles.html","styles.jpg","styles.exe"],0,"CSS files typically use the .css extension."],["Which selector targets every paragraph?",["p",".p","#p","paragraph"],0,"The element selector p targets paragraph elements."],["Which selector targets class=\"notice\"?",[".notice","#notice","notice:","<notice>"],0,"The dot prefix identifies a CSS class selector."],["Which selector targets id=\"contact\"?",["#contact",".contact","contact()","@contact"],0,"The hash prefix identifies a CSS ID selector."],["Why use a class on several service cards?",["Reuse the same styling rule","Make all cards confidential","Convert them into hyperlinks","Automatically store their content"],0,"A class lets multiple elements share a styling rule."],["Which selector styles h1 and h2 together?",["h1, h2","h1 > h2 only","h1 + h2 only","h1.h2"],0,"Comma-separated selectors form a selector list."],["Which selector targets links inside navigation?",["nav a","nav + a","a:nav","nav.a"],0,"nav a selects descendants that are links inside a nav element."],["Which property changes the text colour?",["color","background-color","border-width","font-family"],0,"color sets the foreground text colour."],["Which property changes an element background?",["background-color","font-weight","line-height","text-align"],0,"background-color sets a background fill."],["Which property changes the font family?",["font-family","font-shadow","color-family","text-style"],0,"font-family selects a sequence of typefaces."],["Which property changes the size of the text?",["font-size","text-width","size-font","paragraph-size"],0,"font-size controls text size."],["What does line-height influence?",["The distance between lines of text","The number of webpages","The colour of a link","The size of a CSS file"],0,"Line height affects vertical spacing of text lines."],["Which property adds space inside an element border?",["padding","margin","outline","visibility"],0,"Padding creates space between content and its border."],["Which property adds space outside an element border?",["margin","padding","background-color","font-weight"],0,"Margin controls the space outside an element boundary."],["Which property makes a visible border?",["border","font-style","src","alt"],0,"The border property can define the style, thickness and colour."],["Which choice is a valid hexadecimal colour?",["#155c5a","155c5a#","rgb#155","color@red"],0,"Hex colours begin with # followed by hexadecimal digits."],["If equally specific rules set p to blue then green, which generally wins?",["The later green rule","The first blue rule always","Neither rule","Both values are displayed"],0,"When importance and specificity match, later declarations generally win."],["In p {color: blue} and .notice {color: green}, what applies to <p class=\"notice\">?",["Green","Blue","No colour at all","Green and blue alternating"],0,"At the same cascade level, the class rule is more specific."],["Which is the best first check when an external stylesheet has no effect?",["Check the href path and filename","Add more HTML tables","Rename every heading","Remove all links"],0,"A missing or incorrect stylesheet path prevents its rules from loading."],["Which approach supports consistent styling across several webpages?",["A shared external CSS file","Different inline styles on every word","An image of each webpage","A separate handwritten note"],0,"Multiple HTML pages can link to the same external CSS file."],["Why is good text/background contrast important?",["It helps visitors read information","It automatically checks permissions","It replaces useful headings","It stores user responses"],0,"Readable contrast supports users with different vision and devices."],["Can CSS alone secure confidential records?",["No, security needs proper system controls","Yes, when using dark colours","Yes, by hiding text with CSS","Yes, when adding padding"],0,"CSS affects display; it cannot enforce secure access to records."],["How do you change a link colour in CSS?",["a { color: #125f60; }","a { href: green; }","link { file: green; }","a <color> green"],0,"The color property styles the text of links."],["Which CSS unit is relative to the root element font size?",["rem","px","cm","s"],0,"rem is relative to the root font size."],["Which of these helps visitors recognise a hyperlink?",["An underline or clear link style","Making links identical to all other text","Replacing every link with an image","Removing the link label"],0,"Links should be visually distinguishable and understandable."]],
 unit6:[["Which HTML element groups the controls in a form?", ["<form>", "<table>", "<meta>", "<footer>"], 0, "The form element contains controls such as inputs, selects and buttons."], ["What is the main purpose of a form?", ["To accept information from a user", "To display only a data table", "To set the website font", "To create a webpage address"], 0, "Forms provide controls for users to enter or choose information."], ["Which element gives a text box an accessible description?", ["<label>", "<div>", "<hr>", "<title>"], 0, "A label names a form control and can be linked using for and id."], ["For a label to refer to an input, which values should match?", ["The label's for and input's id", "Both inputs' placeholders", "The label's class and the form's action", "The form method and the input type"], 0, "A label's for attribute should match the targeted control's id."], ["What is the role of a form control's name attribute?", ["It supplies a key for submitted data", "It sets the input colour", "It changes the user's identity", "It stores answers in a database"], 0, "A successful named control contributes a name-value pair during submission."], ["Which input type is best for a contact email?", ["type=\"email\"", "type=\"number\"", "type=\"date\"", "type=\"color\""], 0, "Email type enables basic email-format checking and appropriate mobile keyboards."], ["Which input type is more suitable for a telephone number?", ["type=\"tel\"", "type=\"number\"", "type=\"range\"", "type=\"date\""], 0, "Telephone values may include leading zeros, plus signs and formatting characters."], ["Which element accepts a longer, multi-line message?", ["<textarea>", "<option>", "<legend>", "<br>"], 0, "Textarea provides an editable area for multi-line text."], ["Which control allows a visitor to pick exactly one option from a group?", ["Radio buttons sharing the same name", "Three unrelated checkboxes", "Three paragraphs", "A list of images"], 0, "Radio buttons form a mutually exclusive group when they share a name."], ["Which control is suitable for independent yes/no permission?", ["A checkbox", "A heading", "A caption", "A link"], 0, "A checkbox represents a single independent on/off option."], ["Which two HTML elements create a drop-down list of options?", ["<select> and <option>", "<table> and <td>", "<nav> and <a>", "<p> and <strong>"], 0, "Select is the control and option defines each available choice."], ["What does required do on a suitable input?", ["Makes the browser check that a value is provided", "Saves the answer automatically", "Sends an email instantly", "Protects records from all threats"], 0, "Required is a client-side constraint that requests a value before normal submission."], ["Which attribute can set a minimum length for user-entered text?", ["minlength", "maxlengthonly", "minwords", "rowsize"], 0, "minlength sets a lower length bound for applicable text controls."], ["Which attribute provides a short hint inside a text field?", ["placeholder", "action", "method", "scope"], 0, "Placeholder can offer a hint but should not replace a visible label."], ["Why should each input id generally be unique on a page?", ["Labels and other references need an unambiguous target", "To increase font size", "To ensure every field is mandatory", "To give all fields the same name"], 0, "Duplicate ids can disrupt labels, scripts and accessibility."], ["Which element labels a group of radio buttons?", ["<legend> inside <fieldset>", "<footer> inside <nav>", "<caption> inside <img>", "<td> inside <textarea>"], 0, "Fieldset groups related controls and legend names the group."], ["Which button submits the associated form?", ["<button type=\"submit\">", "<button type=\"button\">", "<button type=\"menu\">", "<button type=\"resetonly\">"], 0, "A submit button triggers form submission, subject to validation."], ["What is one drawback of using a reset button unnecessarily?", ["It may erase entries a visitor has already typed", "It always submits the form", "It saves confidential records", "It changes GET into POST"], 0, "An unexpected reset can make users lose work."], ["What does the action attribute identify?", ["The destination that receives submitted form data", "The font family", "The form border colour", "The number of inputs"], 0, "Action specifies the target URL for submission."], ["What does method specify?", ["How the browser sends submitted form data", "The number of paragraphs", "The CSS style of the form", "The server's physical location"], 0, "The method is commonly GET or POST."], ["What typically happens when a GET form is submitted?", ["Data is encoded in the URL query string", "A database is automatically created", "All inputs become invisible", "The browser creates a PDF"], 0, "GET commonly puts name-value pairs in a query component of the destination URL."], ["What is commonly true about a POST form submission?", ["The values are sent in the request body", "The values must always be visible in the URL", "HTTPS becomes unnecessary", "No server is required"], 0, "POST sends form data in the request body; secure transport still matters."], ["Does using POST alone encrypt submitted values?", ["No, HTTPS is still needed for transport security", "Yes, POST always encrypts everything", "Only if labels are present", "Only for radio buttons"], 0, "POST is a method, not an encryption mechanism."], ["Can HTML alone save a form's answers in an institutional database?", ["No, processing infrastructure is also required", "Yes, any HTML form automatically saves to SQL", "Yes, but only with an id", "Yes, with a placeholder"], 0, "Storage and processing normally require a suitable back-end service."], ["Does type=email prove that an email address belongs to a real person?", ["No, it only checks basic format", "Yes, it verifies the mailbox owner", "Yes, it authenticates the student", "Only if the label is bold"], 0, "Browser format checks cannot verify address ownership."], ["What should happen before a real records request reveals restricted information?", ["The service should check authorisation and access rules", "An HTML form should be displayed", "The form should have at least three colours", "The page should use a table layout"], 0, "Access control requires enforceable checks beyond an HTML form."], ["Which details should be used in classroom practice forms?", ["Invented book titles, references and contact details", "Actual staff passwords", "Private borrower records", "Confidential institutional files"], 0, "Fictional data avoids unnecessary exposure of personal or restricted information."], ["What does a disabled form control normally do when the form is submitted?", ["It is not included in submitted form data", "It is submitted twice", "It becomes automatically required", "It changes into a paragraph"], 0, "Disabled controls are not successful controls in form submission."], ["Which type of control is appropriate for selecting a visit date?", ["<input type=\"date\">", "<input type=\"email\">", "<textarea type=\"date\">", "<input type=\"password\">"], 0, "Date input provides a date-selection interface where the browser supports it."], ["What is a suitable way to make a long form easier to use?", ["Group related controls and use clear labels", "Remove all labels", "Ask for every possible item", "Use one text box for all answers"], 0, "Clear structure and concise questions improve usability."], ["Why is server-side validation still needed?", ["Browser checks can be bypassed and cannot enforce access rules", "HTML labels replace data checks", "GET requests are always secure", "Radio buttons can authenticate users"], 0, "The processing system must check submitted content and relevant permissions."], ["What is the most suitable control for choosing one public records category from many?", ["A labelled select dropdown", "An image without alt text", "A large decorative heading", "A table caption"], 0, "A dropdown is useful for a defined list of categories."]],
 unit5:[["What is a table mainly used for in HTML?", ["Presenting related information in rows and columns", "Positioning the entire homepage", "Encrypting data", "Sending form responses"], 0, "Tables represent structured data, not page layout or server actions."], ["Which element contains an HTML table?", ["<table>", "<td>", "<p>", "<nav>"], 0, "The table element is the outer container for tabular data."], ["Which element identifies a table row?", ["<tr>", "<td>", "<th>", "<caption>"], 0, "tr stands for table row."], ["Which element is an ordinary data cell?", ["<td>", "<th>", "<tr>", "<thead>"], 0, "td represents a data cell within a table row."], ["Which element creates a table header cell?", ["<th>", "<p>", "<td>", "<li>"], 0, "th creates a header, whose relationship to data cells can be clarified by scope."], ["What does <caption> provide?", ["The title or purpose of a table", "An invisible password", "A footnote on every row", "A row of data values"], 0, "A caption briefly describes the entire table."], ["Where should <caption> be placed?", ["Immediately after the opening <table> tag", "Inside every <td>", "Only after </table>", "Outside the webpage body"], 0, "Caption is a child of table and should be its first element child."], ["What does scope=\"col\" mean on a <th>?", ["The header describes cells in its column", "The header describes an entire website", "The header is a CSS class", "The cell must span two rows"], 0, "scope=col associates a header with its column."], ["What does scope=\"row\" mean on a <th>?", ["The header describes cells in its row", "The table has only one row", "The page scrolls horizontally", "The heading must be centred"], 0, "scope=row associates the header with its row."], ["What element normally holds the main data rows?", ["<tbody>", "<thead>", "<title>", "<footer>"], 0, "tbody groups the main body rows."], ["Which element usually groups the column header rows?", ["<thead>", "<tbody>", "<tfoot>", "<section>"], 0, "thead groups header rows."], ["What is an appropriate use of <tfoot>?", ["A total or summary row where useful", "Every individual book title", "The main website footer", "A navigation menu"], 0, "tfoot can group table summaries or totals."], ["What does colspan=\"2\" mean?", ["One cell spans two columns", "One row contains two forms", "Two tables appear side by side", "A cell has two captions"], 0, "colspan determines how many columns a cell occupies."], ["What does rowspan=\"3\" mean?", ["One cell spans three rows", "One table has exactly three rows", "Three headers are compulsory", "A cell has three colours"], 0, "rowspan specifies how many rows one cell occupies."], ["Why are excessive merged cells discouraged?", ["They make tables harder to read and interpret", "They automatically delete records", "They require JavaScript", "They prevent images from loading"], 0, "Complex spans can make header-to-data relationships more difficult."], ["How many rows are in a table with one header row and three book entries?", ["Four", "Three", "One", "Seven"], 0, "The single header row plus three data rows gives four rows."], ["Which is the best table caption?", ["Sample library catalogue", "Table", "Click here", "Untitled"], 0, "A useful caption identifies the data contained in the table."], ["Which information is suitable for a book catalogue table?", ["Title, author, publication year and availability", "Staff passwords", "Unrelated paragraphs and images for page layout", "CSS selectors only"], 0, "Catalogue fields are related attributes of each book entry."], ["Which information is suitable for a public records inventory?", ["Public category, fictional reference, year and access guidance", "Private medical files", "Staff payroll passwords", "Secret case details"], 0, "A public example should use safe structured information."], ["What should you use for a column label such as Author?", ["<th scope=\"col\">Author</th>", "<td scope=\"col\">Author</td>", "<tr>Author</tr>", "<p>Author</p>"], 0, "A header cell with column scope identifies the author column."], ["What is the correct order of nested elements for a data cell?", ["<table> → <tr> → <td>", "<td> → <table> → <tr>", "<caption> → <html> → <td>", "<tr> → <body> → <table>"], 0, "Rows belong inside the table and cells belong inside rows."], ["What is the likely effect of a missing <td> cell?", ["Other values may appear under the wrong column", "The browser automatically creates a database", "The page stops having a title", "The table becomes private"], 0, "Missing cells can misalign values and headers."], ["How is HTML different from CSS when working with tables?", ["HTML gives table structure; CSS controls presentation", "HTML is only for colours", "CSS writes table rows automatically", "They are identical languages"], 0, "HTML identifies meaningful table parts; CSS can style their appearance."], ["Should tables be used for arranging all homepage sections?", ["No; use tables for tabular data", "Yes; all webpages must be tables", "Only when JavaScript is disabled", "Only on mobile phones"], 0, "Modern page layout should not rely on data-table markup."], ["How can a wide table remain usable on a small screen?", ["Allow horizontal scrolling and simplify columns where possible", "Remove all headings", "Make text unreadably small", "Change every cell into an image"], 0, "Horizontal scrolling can preserve table structure on small screens."], ["Why is the <th> element better than a visually bold <td> for a header?", ["It communicates the header meaning programmatically", "It always makes a database", "It removes the need for rows", "It prevents copying"], 0, "Header semantics help readers and assistive technologies."], ["What must every data row of a simple four-column table contain?", ["Four corresponding cells unless spans deliberately change the structure", "Only one cell", "Exactly six headings", "No <tr> tags"], 0, "Matching cell counts keep entries aligned with their columns."], ["When adding a new book to a table, which HTML is added?", ["A new <tr> with suitable cells", "A new <html> inside every row", "A <footer> instead of a row", "A <form> for each word"], 0, "Each new book is another row in the catalogue."], ["Which practice protects confidentiality in a class project?", ["Use fictional, non-sensitive sample entries", "Copy private library borrower records", "Include live employee identifiers", "Display actual restricted record files"], 0, "Never expose protected real-world records in a public-facing demonstration."], ["What does an accessible table communicate?", ["How headers and data cells relate", "Only the font colour", "A hidden login password", "Only the number of images"], 0, "Correct markup connects data cells to meaningful headers."]],
 
 unit1:[
 ['Which statement best describes the World Wide Web?',['A system of linked resources accessed over the Internet','The cables that physically connect all countries','Exactly the same thing as the Internet','A particular web browser'],0,'The Web is a service using Internet infrastructure; the Internet supports other services too.'],
 ['What is a web browser primarily used for?',['Publishing domain names','Requesting and displaying webpages','Protecting all websites from crime','Storing every website on a personal computer'],1,'A browser requests web resources and interprets them for display.'],
 ['What does HTML mainly provide?',['The structure and meaning of webpage content','The annual cost of web hosting','The physical Internet connection','Only the animation effects on a webpage'],0,'HTML describes the content structure and meaning through elements.'],
 ['Which technology mainly controls colours, fonts and spacing?',['DNS','CSS','HTML','HTTP'],1,'CSS is the style language that controls how webpage content is presented.'],
 ['Which technology commonly adds interaction to a webpage?',['JavaScript','A domain name','An IP address','A web browser bookmark'],0,'JavaScript can add behaviour such as responding to clicks or updating displayed information.'],
 ['What does HTTPS indicate about the connection?',['The website is completely trustworthy','The site was made by a university','Web communication is encrypted in transit','The content is free to use'],2,'HTTPS helps protect communication in transit. It does not guarantee the site is honest or safe.'],
 ['What is a website?',['A collection of related webpages or resources identified under a web presence','A synonym for an Internet service provider','A single computer keyboard','Any file stored on a desktop'],0,'A website commonly groups linked pages and resources under a domain or web address.'],
 ['A URL is best described as…',['The address used to locate a web resource','A particular style of HTML heading','The size of a file','The organisation that owns the Internet'],0,'A URL identifies the location of a resource and often shows the scheme, host and path.'],
 ['What does a domain name do?',['It provides a human-readable name for an Internet resource','It controls font colours','It replaces every possible web server','It automatically makes content confidential'],0,'Domain names are easier for people to use than numeric network addresses.'],
 ['What is web hosting?',['Printing a webpage','Providing infrastructure that makes web content available','Changing heading tags','A page layout technique'],1,'Hosting provides the server or platform used to serve a website.'],
 ['Which task normally requires server-side or managed backend functionality?',['Displaying static opening hours','Showing a heading and paragraph','Updating borrowing records in a protected database','Changing a font colour in CSS'],2,'An authenticated database update needs backend functionality rather than only static HTML.'],
 ['A static website can still…',['Contain text, images, links and browser-side interactions','Automatically provide secure confidential databases without services','Never use CSS','Never be used by a library'],0,'Static pages can include useful HTML, CSS and JavaScript but lack an automatic server-side application.'],
 ['Which example is confidential information that should not appear on a public records-centre page?',['Office opening hours','A public telephone number','General access procedures','Personal details from protected files'],3,'Public pages must not expose personal or restricted records.'],
 ['When a browser requests a page, which system commonly sends the response?',['The monitor','A web server','The keyboard','A word processor'],1,'A web server processes requests and serves resources or application responses.'],
 ['In https://library.example.org/catalogue, which part is the host?',['https','library.example.org','/catalogue','All of the address except the protocol'],1,'The host is library.example.org; /catalogue is the path.'],
 ['Which is the most appropriate first webpage for a fictional library?',['A homepage with clear services and hours','A page exposing borrower passwords','A page with nothing except a decorative image','A page requiring a database before any content is visible'],0,'A basic information page can be useful without storing private data or building a backend.']
 ],
 unit2:[
 ['What is the strongest sign that a website is well designed?',['It uses the most colours','Visitors can complete key tasks clearly and efficiently','Every page has animation','Its homepage contains every detail'],1,'Good web design helps the intended audience find and use information effectively.'],
 ['User-centred design begins by identifying…',['Favourite fonts of the designer','Visitors, their tasks and usage conditions','Only the office logo','The number of CSS files'],1,'Knowing who the visitors are and what they need guides effective choices.'],
 ['Which is a typical main task on a university library website?',['Searching a catalogue','Viewing confidential loan passwords','Installing a web server','Editing the university payroll'],0,'Catalogue access is a common library-user task and should be easy to find.'],
 ['What does information architecture describe?',['How content is organised and named','The price of a domain','Only the colour palette','The number of staff in a department'],0,'Information architecture makes information predictable to find.'],
 ['Which navigation label is clearest for an ordinary visitor?',['Client Retrieval Transactions','CRTX','Request a Record','Miscellaneous Transaction Services'],2,'Clear labels describe tasks using familiar user-facing words.'],
 ['What is a sitemap?',['A diagram showing website page structure','A printed map of the city','A user password database','A list of all Internet computers'],0,'A sitemap shows the main pages and how they are related.'],
 ['Why does consistency matter?',['It makes every page identical in content','It reduces the need to relearn navigation and controls','It prevents websites from loading on phones','It removes the need for headings'],1,'Consistent navigation, styles and behaviour make a site easier to use.'],
 ['What is visual hierarchy?',['Arranging content so important information receives attention first','Making all text the same size','Using as many fonts as possible','Hiding the main action'],0,'Hierarchy uses scale, position, contrast and spacing to suggest reading priority.'],
 ['What is the purpose of whitespace?',['To leave the website unfinished','To separate content and make relationships clearer','To increase file size','To force visitors to scroll'],1,'Intentional spacing improves grouping and readability.'],
 ['Which is most likely to improve readability?',['Tiny grey text on a pale background','Long paragraphs in ALL CAPITALS','Legible type, appropriate spacing and contrast','Five different decorative fonts'],2,'Readable typography and sufficient contrast make information easier to understand.'],
 ['Why is colour alone a poor method of signalling an error?',['Users always prefer black text','Some users may not distinguish the colours; messages need text too','HTML does not support colours','Colour cannot appear on mobile screens'],1,'Accessible feedback combines words and visual cues rather than relying on colour.'],
 ['Which is better link wording?',['Click here','More','Download borrowing guidelines (PDF)','Link'],2,'Descriptive text tells users what a link will open or do.'],
 ['How does a button usually differ from a link?',['Buttons typically trigger an action; links navigate','Buttons always lead to other websites','Links are used only in printed documents','There is no useful distinction'],0,'The control type should match the expected user action.'],
 ['What is responsive design?',['A design that changes layout for different screen sizes','A website that replies to every email','A homepage that contains only a picture','A website that uses one fixed width everywhere'],0,'Responsive layouts adapt to available space and device conditions.'],
 ['Which practice supports keyboard users?',['Removing every focus indicator','Keeping controls usable by keyboard with visible focus','Requiring mouse-only actions','Replacing headings with images'],1,'Keyboard operability and visible focus are important accessibility practices.'],
 ['What is a wireframe?',['A basic sketch of page structure and priorities','The finished computer network','A secure records database','A CSS colour definition'],0,'Wireframes plan layout and information placement before coding and decoration.'],
 ['Which action is most suitable for a public records-centre homepage?',['Expose restricted file lists','Show procedures, eligibility and contact guidance','Publish personal IDs','Allow anonymous editing of official records'],1,'Public information should explain services while protected records stay restricted.'],
 ['Which statement is an actionable improvement recommendation?',['The site is ugly','Make the design better','Rename “Client Retrieval Transactions” to “Request a Record” so visitors understand the service','Use more colours everywhere'],2,'A useful recommendation identifies a specific change and why it benefits users.'],
 ['What should a public-facing online form do?',['Ask for every possible personal detail','Use unclear placeholder-only fields','Request only necessary details and clearly label controls','Show every submitted record publicly'],2,'Forms should be understandable and minimise unnecessary data collection.'],
 ['How should an image of important opening-hours information be handled?',['Provide the hours as accessible text','Keep hours only in an image without description','Hide it behind a login even when public','Make the image as small as possible'],0,'Important information should be available as text rather than only as unreadable image content.'],
 ['A user cannot find library hours because they are buried under an unrelated menu. What should change first?',['Move hours to a clear, expected location','Add more animations','Change every button colour randomly','Remove the navigation'],0,'An information-location problem is best fixed by improving structure and labelling.'],
 ['Which explains a good decision for a catalogue search box?',['It is the designer’s favourite shape','Searching resources is a frequent user task, so search appears prominently','It looks impressive in a presentation','It makes all other links unnecessary'],1,'Good design decisions connect placement to real users’ needs.']
 ],
 unit3:[["What does HTML stand for?", ["HyperText Markup Language", "Hyperlink Transfer Management Layer", "High Technology Machine Language", "Home Tool Markup Library"], 0, "HTML means HyperText Markup Language, the standard markup language for webpage structure."], ["What is the main purpose of HTML?", ["To define content structure and meaning", "To permanently store secure records", "To buy website hosting", "To create only colour themes"], 0, "HTML identifies headings, paragraphs and other structured content."], ["Which technology mainly controls webpage layout and colours?", ["HTML", "CSS", "DNS", "A web domain"], 1, "CSS handles most presentation decisions; HTML describes content structure."], ["What does <!DOCTYPE html> represent?", ["A modern HTML document declaration", "An opening body tag", "A link to an external stylesheet", "A closing head tag"], 0, "DOCTYPE is a document declaration, not an ordinary HTML tag."], ["Which element contains the visible webpage content?", ["<head>", "<title>", "<body>", "<meta>"], 2, "The body contains the headings, paragraphs and other content shown in the page."], ["Which element usually contains the browser-tab title?", ["<title>", "<h1>", "<p>", "<footer>"], 0, "The title element is placed in head and names the page in the browser tab."], ["What does the lang=\"en\" attribute specify?", ["The document uses English as its primary language", "The website is encrypted", "The page must be online", "The website contains only English links"], 0, "The lang attribute communicates the document language to software and accessibility tools."], ["What is a complete HTML element in this example?", ["<p>Hours available</p>", "<p>", "</p>", "Hours available"], 0, "A normal element includes opening tag, content and closing tag."], ["What does the slash indicate in </p>?", ["A closing tag", "An empty string", "A comment", "A file path"], 0, "The slash distinguishes a closing tag from an opening tag."], ["Which HTML fragment is correctly nested?", ["<p>Ask a <strong>librarian</strong>.</p>", "<p>Ask a <strong>librarian</p></strong>", "<p><strong>Ask for help</p></strong>", "<strong><p>Help</strong></p>"], 0, "Finish the inner strong element before closing its outer paragraph."], ["Which attribute creates an identifier for one element?", ["id", "href", "src", "charset"], 0, "id identifies one element uniquely within the page."], ["Which attribute can group multiple elements for styling later?", ["class", "doctype", "title-element", "body"], 0, "class can be reused across elements, including for applying shared CSS later."], ["Which heading is normally the main page heading?", ["<h1>", "<h6>", "<p>", "<head>"], 0, "h1 typically represents the main heading of a page."], ["What is the appropriate use of <h2>?", ["A subsection under the main heading", "A substitute for every paragraph", "A command to change the URL", "An HTML comment"], 0, "h2 introduces a section below the higher-level heading."], ["Which element represents a paragraph?", ["<p>", "<br>", "<meta>", "<hr>"], 0, "p groups sentences into a paragraph."], ["Which is a void element that does not take a closing tag?", ["<br>", "<p>", "<h1>", "<strong>"], 0, "br is a void element used for a meaningful line break."], ["What does <strong> usually communicate?", ["Strong importance of text", "A guaranteed larger font size everywhere", "A database request", "The page language"], 0, "strong marks importance; visual bold styling is common but not its semantic purpose."], ["What does <em> communicate?", ["Stress emphasis", "The end of a paragraph", "An external email link", "Page metadata"], 0, "em indicates stress emphasis; browsers often display it in italics."], ["Which character reference displays the ampersand symbol?", ["&amp;", "&lt;", "&gt;", "&quot;"], 0, "&amp; is the character reference used to display an ampersand."], ["Which example is an HTML comment?", ["<!-- Opening hours may change -->", "<comment>Opening hours</comment>", "// Opening hours", "## Opening hours"], 0, "HTML comments start with <!-- and end with -->."], ["What should never be stored in an HTML comment?", ["Passwords or confidential records", "A reminder to check opening hours", "An explanation of the code", "The purpose of a section"], 0, "Source comments can be viewed by site visitors and are not confidential."], ["Which filename is suitable for a first HTML homepage?", ["index.html", "index.html.txt", "index.docx", "homepage.exe"], 0, "The .html extension identifies an HTML file. index.html is a common homepage filename."], ["After editing a local HTML file, what usually shows the latest changes?", ["Save the file and refresh the browser", "Replace the monitor", "Change the domain name", "Install a database"], 0, "The browser needs to load the saved updated file, usually by refreshing."], ["Which statement about HTML-only pages is accurate?", ["They can show useful public information without a database", "They securely authenticate records users by themselves", "They automatically store borrower passwords", "They require a paid host to open locally"], 0, "Basic static pages can present useful public information locally without a backend."], ["Which is a good first HTML activity for records-management students?", ["Create a fictional public service-information page", "Publish real confidential records", "Collect staff passwords in the source", "Offer unauthorised access to protected files"], 0, "Public information pages are an appropriate beginner exercise; real confidential material must be excluded."]],
 unit4:[["Which HTML element creates a hyperlink?",["<a>","<link>","<img>","<nav>"],0,"An anchor (a) element with an href creates a hyperlink."],["What does the href attribute specify?",["The destination of a hyperlink","The image width","The title of a browser tab","The body text colour"],0,"href specifies the resource or location that a hyperlink opens."],["Which link text is most descriptive?",["Library opening hours","Click here","More","Link 2"],0,"Meaningful text describes the destination without relying on nearby context."],["What is an absolute URL?",["A complete web address including its scheme and host","A link to a file in the current folder only","A heading within a paragraph","A path that always starts with ../"],0,"An absolute URL gives a full address such as https://example.org/services.html."],["Which relative path links from index.html to pages/services.html?",["pages/services.html","../services.html","services/../pages","index.html/services.html"],0,"The services file is in the pages subfolder of the homepage folder."],["You are editing pages/services.html. Which path points to root index.html?",["../index.html","index.html","pages/index.html","../../index.html"],0,"../ moves up from pages/ to the containing folder, where index.html sits."],["What does ../ mean in a relative path?",["Move up one directory","Move down one directory","Create a webpage","Search the Internet"],0,"Two dots followed by a slash identifies the parent directory."],["What does #opening-hours refer to?",["An element with id=\"opening-hours\"","A separate domain name","A phone number","An image filename"],0,"A fragment identifier points to a matching element ID within a page."],["Which is a correctly matched section link?",["<a href=\"#hours\">Hours</a> and <h2 id=\"hours\">Hours</h2>","<a href=\"hours\">Hours</a> and <h2 class=\"hours\">Hours</h2>","<a src=\"#hours\">Hours</a>","<p href=\"#hours\">Hours</p>"],0,"A fragment href must match a destination id."],["What does mailto: commonly do?",["Offers to open the visitor’s email application","Creates a secure server-side form","Sends an email without user involvement","Makes a private webpage"],0,"mailto links usually open the configured email client; they do not send messages themselves."],["What is the correct use of an unordered list?",["A set of library services with no necessary order","A step-by-step procedure that must be followed in order","An HTML page title","The main webpage region"],0,"An unordered list groups items whose sequence is not essential."],["Which elements create an ordered list and its items?",["<ol> with <li>","<ul> with <p>","<dl> with <h2>","<nav> with <dd>"],0,"ol groups ordered items and li identifies each item."],["Which kind of list is best for request steps in a specific sequence?",["<ol>","<ul>","<dl>","<section>"],0,"Ordered lists convey meaningful sequence, such as steps in a procedure."],["Which elements identify terms and definitions?",["<dt> and <dd>","<tr> and <td>","<h1> and <p>","<a> and <img>"],0,"dt and dd provide a term and its description inside a dl."],["What is the primary purpose of an image alt attribute?",["Provide a meaningful text alternative to an image","Select a background colour","Force the image to be high resolution","Store a hidden password"],0,"Alternative text helps people who cannot see the image understand its informational function."],["Which alt value is generally suitable for a purely decorative image?",["alt=\"\"","alt=\"decorative decorative decorative\"","No alt attribute under any circumstances","alt=\"image.jpg\""],0,"An empty alt attribute marks an image as decorative for assistive technologies."],["Which attribute points to the image file?",["src","href","id","lang"],0,"src gives the image file location in the img element."],["Which statement about <img> is correct?",["It is a void element and has no closing tag","It must always have </img>","It is only used inside tables","It creates a hyperlink by itself"],0,"An HTML image element has no closing tag; it uses attributes such as src and alt."],["Why do width and height attributes often help image loading?",["They help reserve layout space before the image loads","They encrypt the image","They guarantee the same display size on every screen","They replace alternative text"],0,"Image dimensions allow the browser to reserve space and reduce unwanted layout shifts."],["What does <figcaption> provide?",["A caption associated with a figure","A replacement for all hyperlinks","A webpage title","A hidden web password"],0,"figcaption supplies a visible caption for a figure."],["Which element identifies a main navigation section?",["<nav>","<meta>","<br>","<em>"],0,"nav indicates a region containing navigation links."],["Which element contains the primary content of a webpage?",["<main>","<footer>","<title>","<head>"],0,"main identifies the principal content unique to that page."],["Which element usually contains concluding information or contact details?",["<footer>","<img>","<ol>","<dt>"],0,"footer is commonly used for contextual or concluding information."],["What is the role of aria-current=\"page\" on a navigation link?",["Identify the link corresponding to the current page","Provide the URL of the homepage","Open a pop-up menu","Hide the link from screen readers"],0,"aria-current=\"page\" helps indicate which navigation item represents the current page."],["What is a useful practice for navigation across three pages?",["Keep labels and ordering consistent","Change every menu label on each page","Use links that point to missing files","Replace all links with plain text"],0,"Consistency allows visitors to find content without relearning the menu."],["Which example should not be published on a public records-centre practice site?",["Real restricted personnel files","General public enquiry opening hours","Fictional service categories","A public contact address"],0,"Real confidential records should not be used in practice websites."],["What is a relative path from pages/contact.html to pages/services.html?",["services.html","../pages/pages/services.html","/contact.html","../../services.html"],0,"Both files are in the same pages/ folder, so services.html is sufficient."],["What should you check when an image does not load?",["Its file name, folder and relative src path","The number of headings on the page only","Whether the site has an ordered list","The font size in a paragraph"],0,"Most beginner image failures involve an incorrect filename or file path."],["Which is a benefit of semantic HTML?",["It communicates page structure to people and assistive technologies","It automatically runs database queries","It encrypts all website files","It replaces the need for any navigation links"],0,"Elements such as header, nav and main provide meaningful structure."],["When using an image found online, what is appropriate?",["Check permission or licensing before reusing it","Assume all public images are free to reuse","Remove attribution required by licence","Publish identifiable borrower photos without permission"],0,"Image reuse should respect permissions, licences and privacy."]],
 unit11: [["What is an online public access catalogue (OPAC) mainly used for?", ["Searching library collection records", "Creating HTML stylesheets", "Tracking website animations", "Hosting online meetings"], 0, "An OPAC helps users discover library resources using catalogue records."], ["What does an integrated library system (ILS) support?", ["Several library operations such as cataloguing and circulation", "Only a picture gallery", "Only text colour settings", "Only web hosting payments"], 0, "An ILS supports coordinated library operations; its public catalogue may be one component."], ["Which platform is an open-source integrated library system?", ["Koha", "DSpace", "ArchivesSpace", "HTML"], 0, "Koha is a free and open-source ILS."], ["Which platform is best known as an institutional repository?", ["DSpace", "Koha", "CSS", "JavaScript"], 0, "DSpace manages, preserves and provides access to digital resources."], ["What is a digital repository designed to manage?", ["Digital resources and descriptive information", "Only classroom timetables", "Monitor screen brightness", "Physical shelving equipment"], 0, "Repositories manage digital objects and their metadata and access."], ["Which is a typical institutional repository item?", ["An approved digital dissertation", "A printer toner cartridge", "A building alarm password", "An unsorted paper stack"], 0, "Digital dissertations and articles are common repository resources."], ["What does metadata mean?", ["Information describing another information resource", "A secret password stored in plain text", "A type of web animation", "A website colour scheme"], 0, "Titles, creators, dates and identifiers are examples of metadata."], ["Which field is an example of bibliographic metadata?", ["Author name", "Monitor size", "Wireless password", "HTML background colour"], 0, "The author is part of the descriptive information about a book."], ["What is a finding aid?", ["A description that helps locate archival materials", "A CSS layout technique", "A personal login token", "A device to scan paper automatically"], 0, "A finding aid describes archival collections and how to locate materials."], ["Which system supports archives description and public discovery?", ["ArchivesSpace", "Koha circulation alone", "A calculator", "An image editor"], 0, "ArchivesSpace supports archives information management and web access to descriptions."], ["Which statement about ArchivesSpace is correct?", ["It manages archival description; it is not a complete digital-file storage solution", "It automatically digitises all archival paper records", "It is a CSS framework", "It is a password manager for browsers"], 0, "ArchivesSpace describes holdings and can link to digital objects held elsewhere."], ["Why is archival context important?", ["It explains who created records and their relationships", "It sets a website font automatically", "It prevents all file deletion", "It replaces every finding aid"], 0, "Creation context and original relationships support meaningful archival interpretation."], ["Which task most clearly calls for an ERMS?", ["Managing retention and access to controlled records", "Changing heading colours", "Publishing one opening-hours paragraph", "Making a presentation theme"], 0, "An ERMS supports managed records throughout their life cycle."], ["What is records disposition?", ["Authorised transfer, retention outcome or disposal under applicable rules", "Changing a webpage link colour", "Renaming a stylesheet", "Automatically deleting every file after a week"], 0, "Disposition follows applicable records policies and retention decisions."], ["Which is a typical records life-cycle activity?", ["Capture or receipt of a record", "Choosing a website wallpaper", "Adding a hover animation", "Buying a domain for an unrelated blog"], 0, "Capture or receipt begins the managed records process."], ["Why does an ERMS need an audit trail?", ["To record relevant actions affecting controlled records", "To increase the font size", "To publish every staff message", "To randomise file names"], 0, "Audit trails support accountability and reconstruct important actions."], ["Which is a key difference between a webpage form and an ERMS?", ["An ERMS can enforce records rules and controls", "An HTML form always stores confidential records securely", "An ERMS is just a heading and button", "A webpage form cannot contain labels"], 0, "A form collects input; an ERMS is a larger system of controlled records functions."], ["What is a content management system (CMS) mainly for?", ["Managing and publishing website content", "Replacing all retention schedules", "Controlling every library loan without extra software", "Enforcing database security solely with CSS"], 0, "A CMS supports website content creation and updates."], ["Which is a commonly used general-purpose CMS?", ["WordPress", "Koha OPAC", "ArchivesSpace only", "A plain PNG file"], 0, "WordPress is a general-purpose content management system."], ["Which institution task suits a CMS well?", ["Authorised staff updating public library notices", "Automatically authenticating patrons through a printed poster", "Managing restricted personnel records with no access rules", "Creating a physical bar code with CSS"], 0, "CMS platforms are useful for regularly updated public content."], ["What is the frontend of a web information system?", ["The interface users see and interact with", "Only an off-site tape backup", "Only the database indexing engine", "A paper records box"], 0, "The frontend contains user-facing pages and controls."], ["What is the backend generally responsible for?", ["Processing requests and applying application rules", "Painting text in the users browser only", "Replacing HTML headings with random text", "Printing books automatically"], 0, "Backends process requests and can enforce rules and permissions."], ["Why might a database be needed in a catalogue application?", ["To store and search organised catalogue records", "To control browser brightness", "To replace all image alt text", "To create browser tabs"], 0, "Databases manage structured data queried by applications."], ["What does API stand for?", ["Application Programming Interface", "Archive Publishing Illustration", "Automatic Page Illustration", "Accessible Printer Inventory"], 0, "An API defines how software components interact."], ["Which example shows an API role?", ["A catalogue frontend requesting search results from an application service", "A student choosing a font size in CSS", "A visitor reading a printed poster", "A clerk arranging folders on a shelf"], 0, "An API can provide an interface between frontend and backend services."], ["What is authentication?", ["Checking the identity of a user", "Deciding the font family", "Assigning a book subject heading", "Placing a footer at the end"], 0, "Authentication establishes identity."], ["What is authorisation?", ["Deciding which actions an identified user may perform", "Verifying that an image has a caption", "Creating a homepage title", "Formatting a list with CSS"], 0, "Authorisation controls permissions after identity is established."], ["Why is hiding a records link with CSS not adequate security?", ["It does not enforce server-side permission checks", "CSS encrypts everything automatically", "It guarantees records cannot be copied", "It prevents staff from opening a file"], 0, "Access restrictions must be enforced by trusted services, not visual hiding."], ["Which should not appear on a public practice website?", ["Real confidential personnel files", "Fictional library services", "Public office opening hours", "Public contact guidance"], 0, "Practice exercises should avoid real restricted and personal information."], ["Why are accurate records metadata important?", ["They improve identification, retrieval and context", "They eliminate the need for any security", "They automatically create physical books", "They make CSS unnecessary"], 0, "Metadata supports discovery and controlled management."], ["Which public service most clearly needs a simple information website?", ["Publishing office opening hours and directions", "Handling confidential employee files", "Managing an authorised retention schedule", "Recording sensitive access events"], 0, "Public hours and directions can be published as ordinary web content."], ["Which feature most clearly needs a specialist library system?", ["Searching books and checking copy availability", "Changing button background colour", "Showing a static contact address", "Displaying a simple three-item list"], 0, "Availability data usually comes from a managed library application."], ["Which task suits an archival description system?", ["Discovering a historical collection and its reference code", "Counting button clicks", "Changing CSS margins", "Selling web hosting packages"], 0, "Archival description systems make collection context and location discoverable."], ["Which task suits a digital repository?", ["Finding and downloading an approved research article", "Approving a confidential retention schedule", "Changing a navigation bar colour", "Labelling physical office keys"], 0, "Repositories provide access to digital scholarly resources."], ["What is a useful purpose of access restrictions in a repository?", ["Keeping restricted items available only to authorised users", "Making every document invisible to search engines forever", "Replacing all descriptive metadata", "Disabling all user interfaces"], 0, "Repository permissions can distinguish openly available and restricted content."], ["Why might a college use both Koha and DSpace?", ["To manage library collection services and digital scholarship respectively", "Because both are CSS stylesheets", "Because websites cannot have two links", "To avoid writing any metadata"], 0, "Different services often require specialised systems."], ["What can a public records portal provide safely?", ["General request procedures for public records", "Unrestricted access to all staff records", "A public list of confidential file passwords", "A bypass for staff authorisation"], 0, "Public guidance can be offered without revealing restricted files."], ["What is information integrity?", ["Protecting information against unauthorised or unintended change", "Adding more animations", "Changing all records to uppercase", "Publishing every draft immediately"], 0, "Integrity means records stay reliable and protected from improper modification."], ["Why is backup relevant to institutional web information systems?", ["It helps restore information after loss or failure", "It replaces the need for user permissions", "It makes every website an archives system", "It removes the need for descriptive metadata"], 0, "Backups support recoverability, although preservation needs may require more."], ["What is a sensible first step when selecting a web information system?", ["Identify user needs, information types and workflows", "Choose the brightest colour palette", "Copy an unrelated website homepage", "Assume one system is always best"], 0, "System selection should begin with user tasks and organisational requirements."], ["A visitor searches for a book, but the interface has no catalogue data. What is the main problem?", ["A search box alone cannot provide real catalogue results", "The page uses a heading", "The page contains a navigation link", "The webpage has too few colours"], 0, "Useful search requires underlying records and suitable application functionality."], ["Why might an archive description link not open the original document?", ["The item may not be digitised or may have access conditions", "Every archival record must be online", "The browser never opens PDF files", "A finding aid is the same as a download"], 0, "Finding aids describe holdings; the original may require a request or separate access."], ["What should authorised staff have that a public visitor may not?", ["Appropriate permissions to manage institutional records", "A hidden CSS colour only", "A different web browser brand", "Automatically published passwords"], 0, "Staff permissions should match their legitimate duties."], ["Which best explains the link between HTML and a web-based information system?", ["HTML can render the interface, but other software may handle searches and data", "HTML itself enforces retention policies", "HTML replaces all catalogue databases", "HTML automatically verifies staff identity"], 0, "HTML structures the visible interface, not every system service."]],
 unit12: [["What is web hosting?", ["A service that makes website files or applications accessible online", "A way of changing text colours", "A type of HTML heading", "A file extension for a photograph"], 0, "Hosting delivers website resources through an online service."], ["What is the main role of a web server?", ["Responding to requests for web resources", "Choosing library books for purchase", "Creating every domain name automatically", "Recording every student grade"], 0, "Web servers deliver resources or application responses to browsers."], ["What does deployment mean in web development?", ["Placing a working website or application on a hosting service", "Changing a paragraph into a list", "Buying a new computer monitor", "Automatically recording library circulation"], 0, "Deployment moves the site into an environment where its visitors can access it."], ["Which file is a common entry page for a static website?", ["index.html", "presentation.tmp", "records.exe", "stylesheet.pdf"], 0, "An index.html file is a typical homepage entry file."], ["Which is a human-readable domain name?", ["example.org", "<h1>Example</h1>", "color: blue;", "C:\\folder\\website"], 0, "A domain is a human-readable name used in web addresses."], ["What is DNS short for?", ["Domain Name System", "Digital Network Spreadsheet", "Document Navigation Script", "Data Notice Service"], 0, "DNS maps names to information used to locate Internet services."], ["What does an A record normally provide?", ["An IPv4 address for a hostname", "A CSS colour palette", "The HTML heading level", "A PDF editing password"], 0, "DNS A records map hostnames to IPv4 addresses."], ["What does a CNAME record normally do?", ["Alias one hostname to another", "Create a library catalogue", "Protect passwords without a server", "Convert HTML into a photograph"], 0, "A CNAME record associates one hostname with another hostname."], ["Which describes a URL?", ["The address identifying a web resource", "Only a computer screen resolution", "A type of webpage font", "A general word for password"], 0, "A URL includes the resource address, often with a scheme, host and path."], ["What does HTTPS mainly add to HTTP?", ["Transport encryption and authenticated connection using TLS", "Automatically approved institution data", "A guarantee that every webpage is honest", "Unlimited web storage"], 0, "HTTPS protects the connection in transit; it is not a complete website security audit."], ["Which statement about HTTPS is correct?", ["It does not replace application access controls", "It automatically prevents all confidential file leaks", "It makes backup unnecessary", "It guarantees every website is trustworthy"], 0, "HTTPS helps protect transport but cannot replace permission checks and secure system design."], ["Which is a typical use for static hosting?", ["Publishing library opening hours and contact information", "Securely managing restricted personnel files with no backend", "Running a full database purely in an HTML paragraph", "Automatically approving confidential record access"], 0, "Static sites work well for straightforward public information."], ["What is a major limitation of a static website alone?", ["It does not provide trusted server-side processing or a secure records database", "It cannot display headings", "It cannot have images", "It cannot link to other websites"], 0, "Static hosting serves resources; secure workflows need separate trusted services."], ["Which type of platform helps staff update public notices?", ["Content management system", "An HTML image caption only", "A screen-saver application", "A paper-only request box"], 0, "A CMS provides managed editing and publication of site content."], ["What is a suitable approach for confidential records workflows?", ["A secure specialist records application with enforced permissions", "Only a public static HTML page", "A hidden link in a public webpage", "A brightly coloured login image"], 0, "Restricted records need real application and organisational access controls."], ["Which technology is typically included in a static website?", ["HTML, CSS and optional browser-side JavaScript", "Only an institutional database server", "Only printed catalogue cards", "Only private staff audit logs"], 0, "Static sites can serve HTML, CSS, JavaScript and media files."], ["What should influence a hosting decision most?", ["Website tasks, technical requirements, information sensitivity and support", "The brightest button colour only", "The shortest provider name only", "How many images appear on the homepage"], 0, "Hosting should fit the use case and organisational needs."], ["Why should free hosting limits be reviewed?", ["Usage restrictions and features may change", "A free service can never display HTML", "Paid hosting is always unsafe", "Domains never require renewal"], 0, "Check current limits, terms and features before choosing a provider."], ["Which ongoing cost may apply to a custom domain?", ["Registration renewal", "An HTML paragraph fee", "A CSS border fee", "A browser tab fee"], 0, "Domain registrations commonly have renewal obligations."], ["What is GitHub Pages used for?", ["Publishing static websites from supported repository sources or workflows", "Automatically creating secure ERMS databases", "Storing confidential student passwords publicly", "Running arbitrary server-side programs on a free static site"], 0, "GitHub Pages serves static site content and supported build outputs."], ["In GitHub Pages branch publishing, which setting is relevant?", ["Repository Settings → Pages → publishing source", "Browser → Print preview only", "CSS → font-family", "HTML → title attribute"], 0, "GitHub Pages publishing source is configured in repository settings."], ["When using GitHub Pages, what should you upload?", ["Actual HTML, CSS and other site files in the correct locations", "Only an unopened ZIP file with no extracted files", "Only a screenshot of the homepage", "Only a Word document listing the site name"], 0, "Pages requires the site entry and resources to exist in the publishing source."], ["A project repository site often uses which address pattern?", ["https://username.github.io/repository-name/", "file://private-computer/site", "C:\\Documents\\index.html", "https://www.example.com by default for every repository"], 0, "GitHub Pages project sites commonly include the repository path in their URL."], ["What risk does a leading slash in a project link introduce?", ["It may resolve from the domain root instead of the project subdirectory", "It automatically creates an HTTPS certificate", "It makes the image more accessible", "It changes the title of a library book"], 0, "Root-relative links can misdirect in project subpaths."], ["Which local file reference will not work for remote visitors?", ["C:\\Users\\Student\\Desktop\\image.jpg", "images/photo.jpg within the uploaded site", "services.html beside index.html", "css/style.css within the uploaded site"], 0, "Computer-specific local paths are not reachable from a public browser."], ["Can a private GitHub repository alone guarantee private Pages access?", ["No, repository visibility and published Pages visibility are different", "Yes, every Pages website becomes private automatically", "Yes, a hidden filename secures it", "Yes, CSS can enforce user authentication"], 0, "Published Pages content is generally public; private repository status is not sufficient access control."], ["What should never be included in a public practice website?", ["Real borrower details, passwords or restricted records", "Invented library opening hours", "A fictional service list", "A CSS file"], 0, "Keep real confidential or identifying information off public practice websites."], ["Which is a sensible library website design?", ["Public hours page that links to a separately hosted catalogue", "Public disclosure of patron borrowing histories", "Publishing staff account passwords beside opening hours", "Putting confidential files inside the images folder"], 0, "Separate public information pages from controlled specialist services."], ["Which is a sensible records-centre website design?", ["Public request guidance with restricted records managed separately", "A public directory containing every personnel record", "A hidden link replacing account permissions", "A page with unsecured private audit logs"], 0, "Public guidance is suitable for static publishing; restricted processing requires controls."], ["Why check a website on a phone?", ["To ensure layout and navigation remain usable at narrow widths", "To make DNS unnecessary", "To change all domain registration dates", "To delete website metadata automatically"], 0, "Responsive and usable pages should work across different screens."], ["Which is an accessibility-related publishing check?", ["Meaningful link text and keyboard access", "Changing every paragraph into an image", "Hiding focus indicators", "Using colour alone to explain every instruction"], 0, "Clear links and keyboard access support accessibility."], ["Why is alternative text useful?", ["It conveys an appropriate text alternative for meaningful images", "It purchases hosting automatically", "It replaces DNS", "It encrypts every file"], 0, "Good alt text supports people using assistive technologies and cases where images fail."], ["Why review copyrights before publishing?", ["Publication requires suitable permissions or licences for content", "All online photos are automatically free to republish", "CSS gives ownership of every image", "A published domain removes copyright law"], 0, "Use original or appropriately licensed/authorised material."], ["What is an important maintenance task?", ["Updating inaccurate opening hours and fixing broken links", "Leaving service procedures unchanged for many years", "Deleting every backup after publication", "Hiding all contact details"], 0, "Outdated website information can mislead users."], ["Why should a website have backups?", ["To support recovery after deletion, error or service failure", "To make links more colourful", "To replace access permissions", "To purchase a domain automatically"], 0, "Backups support service continuity and recovery."], ["Who should control institutional domain and hosting credentials?", ["Authorised responsible persons under agreed governance", "Any website visitor", "Every student by default", "Only someone who guesses the password"], 0, "Institutional ownership and authorised access support continuity and accountability."], ["What should be tested after publishing?", ["Navigation, images, forms and layout using the published URL", "Only whether the HTML editor opens on the author computer", "Only the desktop wallpaper", "Only the slide title"], 0, "Deployment can change resource paths; test from the published site."], ["What is the role of a publishing-readiness checklist?", ["To guide basic pre-publication review", "To certify all institutional security compliance automatically", "To replace software updates forever", "To guarantee a zero-cost hosting contract"], 0, "A classroom checklist helps but does not substitute for appropriate formal controls."], ["What does a custom domain normally require?", ["Correct registration and DNS configuration", "Changing all HTML tags to uppercase", "Removing every stylesheet", "Embedding staff passwords in a footer"], 0, "Custom domain use involves DNS and hosting configuration."], ["What is a browser rendering?", ["Displaying the page after receiving its resources", "Registering a new domain automatically", "Buying server hardware", "Retaining official records indefinitely"], 0, "Browsers interpret website resources to display a page."], ["Which is an example of a provider-supplied site address?", ["student.github.io/project/", "<table>", "font-weight: bold;", "A paper records reference number"], 0, "A provider-supplied URL can work without a purchased custom domain."], ["What does an institution need for a live catalogue?", ["An appropriate application and managed catalogue data", "Only an image of a search bar", "Only one hidden HTML comment", "Only a domain name with no hosting"], 0, "Live searching requires suitable software and underlying information."], ["Why should hosting terms be checked regularly?", ["Features, usage policies and prices can change", "HTML tags expire every week", "DNS stops working whenever a new CSS file is added", "Published photos always become private"], 0, "Providers revise service options and limits."], ["Which order best describes a sensible publishing workflow?", ["Prepare files → test → deploy → test published site → maintain", "Deploy confidential files → choose passwords later", "Buy a domain → ignore the site files → stop", "Hide an image → assume the website is private"], 0, "Publishing includes preparation, deployment, testing and continuing care."]]
 };
 const choose=(arr)=>arr[Math.floor(Math.random()*arr.length)];
 const shuffle=(array)=>{const a=array.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
 document.querySelectorAll('[data-quiz]').forEach(shell=>{
   const bank=banks[shell.dataset.quiz];if(!bank)return;
   const container=shell.querySelector('[data-quiz-questions]');const form=shell.querySelector('[data-quiz-form]');
   const result=shell.querySelector('[data-quiz-result]');const status=shell.querySelector('[data-quiz-status]');const progress=shell.querySelector('[data-quiz-progress]');
   const count=Math.min(8,bank.length);let chosen=[],attempt=0,submitted=false,lastSet='';
   function updateProgress(){const selected=container.querySelectorAll('input[type="radio"]:checked').length;progress.textContent=selected+' of '+count+' answered';}
   function newAttempt(){
     let sample;for(let i=0;i<8;i++){sample=shuffle(bank.map((q,n)=>({q,n}))).slice(0,count);const key=sample.map(x=>x.n).sort((a,b)=>a-b).join(',');if(key!==lastSet){lastSet=key;break;}}
     chosen=sample.map(({q})=>({q,options:shuffle(q[1].map((text,idx)=>({text,idx})))}));attempt++;submitted=false;
     container.replaceChildren();result.replaceChildren();result.style.display='none';
     status.textContent='Attempt '+attempt+' • '+count+' questions';
     chosen.forEach((item,i)=>{
       const fs=document.createElement('fieldset');fs.className='quiz-card';
       const legend=document.createElement('legend');legend.textContent=(i+1)+'. '+item.q[0];fs.append(legend);
       item.options.forEach((option,j)=>{
         const label=document.createElement('label');const input=document.createElement('input');input.type='radio';input.name='q'+i;input.value=String(option.idx);input.id=shell.dataset.quiz+'-a'+attempt+'-q'+i+'-o'+j;
         label.append(input,document.createTextNode(' '+option.text));fs.append(label);
       });
       const feedback=document.createElement('div');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');fs.append(feedback);
       container.append(fs);
     });
     form.querySelector('[type=submit]').disabled=false;updateProgress();
   }
   function addText(parent,tag,txt){const e=document.createElement(tag);e.textContent=txt;parent.append(e);return e;}
   form.addEventListener('change',updateProgress);
   form.addEventListener('submit',e=>{
     e.preventDefault();if(submitted)return;submitted=true;let score=0,missed=0;
     chosen.forEach((item,i)=>{
       const input=container.querySelector('input[name="q'+i+'"]:checked');const chosenIndex=input?Number(input.value):-1;const good=chosenIndex===item.q[2];
       const fs=container.querySelectorAll('fieldset')[i],fb=fs.querySelector('.quiz-feedback');
       if(good){score++;fs.classList.add('answer-correct');addText(fb,'strong','Correct.');}
       else{missed++;fs.classList.add('answer-wrong');addText(fb,'strong',chosenIndex<0?'Unanswered.':'Not correct.');addText(fb,'p','Correct answer: '+item.q[1][item.q[2]]);addText(fb,'p','Why: '+item.q[3]);}
       fb.style.display='block';fs.querySelectorAll('input').forEach(input=>input.disabled=true);
     });
     const pct=Math.round(score*100/count);
     addText(result,'h3','Your score: '+score+' / '+count+' ('+pct+'%)');
     addText(result,'p',missed===0?'Excellent: all answers are correct. Try another attempt for new questions.':missed+' missed or unanswered. Read the corrections below, revise those sections, then choose New shuffled attempt.');
     result.style.display='block';form.querySelector('[type=submit]').disabled=true;
     result.scrollIntoView({behavior:'smooth',block:'nearest'});
   });
   shell.querySelector('[data-quiz-new]').addEventListener('click',()=>newAttempt());
   newAttempt();
 });
})();
